export interface Router { readonly record: Record<string, unknown> }
type Decorated<R> = { [K in keyof R]: { query(): R[K] } };
// A package alias of another alias: the compiler's value type keeps the inner alias only.
export type ProxyOf<R extends Router> = Decorated<R["record"]>;
export declare function createProxy<R extends Router>(): ProxyOf<R>;
// A package alias of a class instance's own alias that the value keeps.
export type HandleOf<R extends Router> = { readonly handle: R; call(): void };
export declare function createHandle<R extends Router>(): HandleOf<R>;
export interface Plain { query(): void }
export declare function createPlain(): Plain;
export declare function untyped(): any;
